package com.masaakis.importer.api;import com.masaakis.importer.application.CatalogProService;import com.masaakis.security.StaffPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.io.IOException;import java.math.BigDecimal;import java.util.UUID;
@RestController@RequestMapping("/api/admin/catalog-pro")public class CatalogProController{private final CatalogProService service;public CatalogProController(CatalogProService s){service=s;}@PostMapping(value="/imports/preview",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)CatalogProService.ImportView preview(@AuthenticationPrincipal StaffPrincipal p,@RequestPart MultipartFile file)throws IOException{return service.preview(p,file);}@PostMapping("/imports/{id}/commit")CatalogProService.ImportView commit(@AuthenticationPrincipal StaffPrincipal p,@PathVariable UUID id){return service.commit(p,id);}@GetMapping(value="/export.csv",produces="text/csv")ResponseEntity<byte[]>export(@AuthenticationPrincipal StaffPrincipal p){return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=menu.csv").contentType(new MediaType("text","csv",java.nio.charset.StandardCharsets.UTF_8)).body(service.exportCsv(p));}@PostMapping("/prices/preview")CatalogProService.BatchView price(@AuthenticationPrincipal StaffPrincipal p,@Valid@RequestBody PriceRequest r){return service.pricePreview(p,r.mode(),r.value());}@PostMapping("/prices/{id}/commit")CatalogProService.BatchView commitPrice(@AuthenticationPrincipal StaffPrincipal p,@PathVariable UUID id){return service.priceCommit(p,id);}@PostMapping("/prices/{id}/rollback")CatalogProService.BatchView rollback(@AuthenticationPrincipal StaffPrincipal p,@PathVariable UUID id){return service.rollback(p,id);}public record PriceRequest(@Pattern(regexp="SET|ADD|PERCENT")String mode,@NotNull BigDecimal value){}}
